(()=>{'use strict';
const {World,TRAITS,RECIPES,RESOURCE_LABOR}=Society,{referenceLaborValues,basketLaborCost}=LaborValue,KEY='vishnu-society-lab-v1',$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=x=>Math.round(Number(x)*100)/100,clock=t=>`${Math.floor(t/60)}h ${t%60}m`;
let world,playing=false,selected='a0',tab='decisions',last=performance.now(),elapsed=0,lastDraw=0,lastSave=0,batch=null,worker=null,storageOK=true,pendingOptions=null;
try{const saved=localStorage.getItem(KEY);world=saved?new World({},JSON.parse(saved)):new World()}catch{world=new World();storageOK=false}
const points={common:[18,32],garden:[43,66],workshop:[63,32],pond:[13,77],grove:[82,36],quarry:[85,80]};
const title={common:'Common',garden:'Garden',workshop:'Workshop',pond:'Pond',grove:'Grove',quarry:'Earth & energy'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(world.snapshot()));storageOK=true}catch{storageOK=false}}
function name(id){return world.agent(id)?.name||id}
function pause(){playing=false;$('#play').textContent='Run'}
function download(filename,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function setSelected(id){selected=id;render(true)}
function selectTab(id){tab=id;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('primary',b.dataset.tab===id));renderView()}
function setup(){const o=world.s.options;$('#seed').value=world.s.initialSeed;$('#count').value=o.count;$('#scenario').value=o.scenario;for(const k of ['gossip','institutions','theft'])$('#'+k).checked=o[k]}
$('#play').onclick=()=>{playing=!playing;$('#play').textContent=playing?'Pause':'Run'};
$('#step').onclick=()=>{pause();world.tick();world.validate();save();render(true)};
$('#hour').onclick=()=>{pause();world.advance(60);world.validate();save();render(true)};
$('#export').onclick=()=>download(`society-${world.s.initialSeed}-${world.s.time}.json`,world.snapshot());
$('#export-graph').onclick=()=>download(`society-graph-${world.s.time}.json`,world.graph());
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));
$('#event-filter').onchange=renderEvents;
function requestReset(options){pause();pendingOptions=options;$('#reset-confirm').showModal()}
$('#new-world').onsubmit=e=>{e.preventDefault();requestReset({seed:Number($('#seed').value),count:Number($('#count').value),scenario:$('#scenario').value,gossip:$('#gossip').checked,institutions:$('#institutions').checked,theft:$('#theft').checked})};
$('#replay').onclick=()=>requestReset({...world.s.options,seed:world.s.initialSeed});
$('#reset-cancel').onclick=()=>$('#reset-confirm').close();
$('#reset-go').onclick=()=>{try{localStorage.setItem(KEY+'-previous',JSON.stringify(world.snapshot()))}catch{storageOK=false}world=new World(pendingOptions);selected='a0';elapsed=0;save();setup();$('#reset-confirm').close();render(true)};
function render(force=false){const a=world.agent(selected)||world.s.agents[0],m=world.metrics();$('#clock').textContent=clock(world.s.time);$('#metrics').innerHTML=[['Residents',m.population],['Trades',m.trades],['Gossip shared',m.gossip],['Disputes settled',`${m.mediations} / ${m.disputes}`],['Discoveries',m.discoveries],['Associations',m.associations]].map(([label,value])=>`<div>${label}<strong>${value}</strong></div>`).join('');
$('#hubs').innerHTML=Object.entries(points).map(([k,[x,y]])=>`<span class="lab-hub" style="left:${x}%;top:${y-13}%">${title[k]}</span>`).join('');
const grouped={};for(const b of world.s.agents)(grouped[b.hub]||=[]).push(b);
$('#actors').innerHTML=world.s.agents.map(b=>{const [x,y]=points[b.hub],i=grouped[b.hub].indexOf(b),angle=i*2.399,radius=grouped[b.hub].length>1?3+Math.sqrt(i)*2:0;return`<button class="lab-actor ${b.id===a.id?'selected':''}" data-agent="${b.id}" data-action="${esc(b.action?.type)}" style="left:${x+Math.cos(angle)*radius}%;top:${y+Math.sin(angle)*radius*1.6}%" title="${esc(b.name)}: ${esc(b.action?.type||'idle')}" aria-label="Inspect ${esc(b.name)}">${esc(b.name.slice(0,2))}</button>`}).join('');
$('#cast').innerHTML=world.s.agents.map(b=>`<button class="button ${b.id===a.id?'selected':''}" data-agent="${b.id}">${esc(b.name)}</button>`).join('');document.querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>setSelected(b.dataset.agent));
$('#map-caption').textContent=`${title[a.hub]} · ${a.name}: ${a.action?.type||'idle'}`;
const speakers=world.s.agents.filter(a=>a.speech&&world.s.time-a.speech.time<8).slice(-2);$('#speech').innerHTML=speakers.map(a=>`<p><strong>${esc(a.name)}:</strong> “${esc(a.speech.text)}”</p>`).join('')||'<p class="fine">Speech is assembled from the action and its evidence. Nothing is generated by an LLM.</p>';
if(!$('#inspector').contains(document.activeElement)||force)renderInspector(a);
if(tab!=='experiments'||force)renderView();renderEvents();$('#storage-status').textContent=storageOK?'Saved locally in this browser. Pause before inspecting or changing a trait.':'Browser storage unavailable. Export your world to keep a copy.'}
function renderInspector(a){$('#inspector').innerHTML=`<h3>${esc(a.name)} <span class="fine">${title[a.hub]}</span></h3><p><strong>${esc(a.action?.type||'idle')}</strong>${a.action?` · ${a.action.end-world.s.time} minutes remaining`:''}</p><div class="needs">${Object.entries(a.needs).map(([k,v])=>`<div class="needrow"><span>${k}</span><div class="bar"><i style="width:${v}%;background:${v>70?'#d88964':'#91b779'}"></i></div><span>${Math.round(v)}</span></div>`).join('')}</div><div class="inventory">${Object.entries(a.inventory).filter(([,v])=>v>.01).map(([k,v])=>`<span>${num(v)} ${k}</span>`).join('')}</div><details id="personality"><summary>Edit personality</summary><form id="trait-form"><div class="lab-traits">${Object.entries(TRAITS).map(([k,help])=>`<label title="${esc(help)}">${help.split(':')[0]}<input type="range" min="0" max="100" name="${k}" value="${a.traits[k]}" aria-label="${help.split(':')[0]}"><output>${a.traits[k]}</output></label>`).join('')}</div><button class="button small">Apply traits</button><p class="fine">Affects future choices. The current action finishes first.</p></form></details><p class="fine">OCEAN: ${Object.entries(a.traits).map(([k,v])=>k+' '+v).join(' · ')}<br>Interests: ${Object.entries(a.interests).map(([k,v])=>k+' '+Math.round(v*100)).join(' · ')}.<br>Skills: gather ${num(a.skills.gather)}, craft ${num(a.skills.craft)}, mediate ${num(a.skills.mediate)}.<br>Food reserve target: ${num(world.reserve(a))}. ${a.group?'Member of '+a.group+'.':''}</p>`;
$('#trait-form').oninput=e=>{if(e.target.type==='range')e.target.nextElementSibling.textContent=e.target.value};$('#trait-form').onsubmit=e=>{e.preventDefault();pause();for(const k of 'OCEAN')a.traits[k]=Number(e.target.elements[k].value);world.log('intervention',[a.id],`Player changed ${a.name}'s OCEAN values.`,{traits:{...a.traits}});save();render(true)};$('#personality').ontoggle=e=>{if(e.target.open)pause()}}
function table(headers,rows){return`<div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function chart(){const h=world.s.history;if(h.length<2)return'';const points=h.map((m,i)=>`${30+i*650/(h.length-1)},${135-m.meanHunger}`).join(' ');return`<svg class="lab-chart" viewBox="0 0 700 160" role="img" aria-label="Mean hunger over this run"><path d="M30 25V135H680" fill="none" stroke="#9cac97"/><polyline points="${points}" fill="none" stroke="#af683b" stroke-width="2"/><text x="35" y="18">Mean hunger: 0–100</text><text x="30" y="151">${clock(h[0].minute)}</text><text x="605" y="151">${clock(h.at(-1).minute)}</text></svg>`}
function renderView(){const a=world.agent(selected),v=$('#view');if(tab==='decisions'){v.innerHTML=`<h3>Why ${esc(a.name)} chose ${esc(a.action?.type||'nothing yet')}</h3><p class="fine">Scores from the last decision. Needs, personality, evidence and commitments contribute separately. When the top two scores differ by less than 3, a seeded 20% variation can choose the second. Actions persist until completion.</p>${a.lastDecision.length?table(['Option','Score','Contributions'],a.lastDecision.map(d=>`<tr><td>${esc(d.type)}${d.resource?' / '+d.resource:''}${d.recipe?' / '+d.recipe:''}${d.partner?' with '+esc(name(d.partner)):''}${d.contract?'<small>'+d.contract+'</small>':''}</td><td><strong>${num(d.score)}</strong><br><span class="score-bar" style="width:${Math.max(2,Math.min(100,d.score))}px"></span></td><td><div class="decision-parts">${Object.entries(d.parts).map(([k,v])=>`<span>${k}: ${v>=0?'+':''}${num(v)}</span>`).join('')}</div></td></tr>`)):'<p>Step once or run the simulation to see its first decisions.</p>'}<details><summary>What each trait changes</summary>${Object.values(TRAITS).map(t=>`<p class="fine">${t}</p>`).join('')}<p class="fine">These are tunable game rules, not a validated model of human psychology. Appearance does not determine skills or personality.</p></details>${chart()}`}
if(tab==='relationships'){const peers=world.s.agents.filter(b=>b!==a&&world.s.edges[a.id+'>'+b.id]);v.innerHTML=`<h3>${esc(a.name)}’s relationships</h3><p class="fine">A directed connection records this resident’s view of someone else. Strangers use neutral trust; they do not receive a record until interaction or a report. Lines below show this resident’s known connections.</p><div class="graph-layout">${graphSVG(a)}<div>${table(['Person','Affection','Trust','Familiarity'],peers.map(b=>{const r=world.relation(a,b,false);return`<tr><td>${esc(b.name)}</td><td>${num(world.affection(a,b))}</td><td>${Math.round(world.trust(a,b)*100)}%</td><td>${num(r.familiarity)}</td></tr>`}))}</div></div><p class="fine">Affection has separate social, help and cooperation contributions. Gifts alone approach a maximum contribution of 15, with reduced strength for repeats. Cooperation does not guarantee friendship.</p>`;v.querySelectorAll('[data-node]').forEach(b=>{b.onclick=()=>setSelected(b.dataset.node);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setSelected(b.dataset.node)}}})}
if(tab==='memories'){v.innerHTML=`<h3>What ${esc(a.name)} knows</h3><p class="fine">Up to 40 significant event records are retained for retelling. Reliability summaries retain deduplicated evidence. A repeated report cannot count as a new incident. Firsthand evidence can replace a weaker rumour. Reports travel at most two hops.</p>${table(['Event / subject','Source','Confidence','Effect'],a.memories.slice().reverse().map(m=>`<tr><td>${esc(m.type)} · ${esc(name(m.subject))}<small>${m.origin} · ${clock(m.time)}</small></td><td>${m.firsthand?'Firsthand':esc(name(m.source))+' told me'}<small>${m.hops} hops</small></td><td>${Math.round(m.confidence*100)}%</td><td>${m.outcome>0?'Supports reliability':'Adverse evidence'}<small>impact ${m.impact}</small></td></tr>`))}<details><summary>Actual saved memory record</summary><pre>${esc(JSON.stringify(a.memories.at(-1)||{note:'No memories yet'},null,2))}</pre></details>`}
if(tab==='contracts'){v.innerHTML=`<h3>Contract registry</h3><p class="fine">Economic trades, commissions, food loans, social meetings, gifts, restitution and association charters share an event ledger. Commissions hold food in escrow. Late delivery opens a dispute; unresolved escrow is returned after 15 minutes. Food loans repay 2.1 for 2 borrowed; repayment is voluntary and default affects trust. Arbitrary legal clauses are not supported.</p>${table(['Agreement','Participants','Terms','State'],world.s.contracts.slice(-70).reverse().map(c=>`<tr><td>${c.id} · ${c.kind}<small>${clock(c.created)}</small></td><td>${esc(name(c.from))} → ${esc(name(c.to))}${c.mediator?'<small>Mediator: '+esc(name(c.mediator))+'</small>':''}</td><td>${esc(c.terms.good||c.terms.activity||'')}${c.terms.price!==undefined?' · '+c.terms.price+' food':''}${c.terms.food?' · '+c.terms.food+' food':''}${c.terms.repayment?'<small>Repayment: '+c.terms.repayment+' food</small>':''}${c.terms.members?'<small>'+c.terms.members.map(name).map(esc).join(', ')+'</small>':''}<small>${c.terms.ask?'Asked '+c.terms.ask+' / buyer limit '+c.terms.max:''}</small></td><td>${c.status}${c.escrow?'<small>'+num(c.escrow)+' food held</small>':''}${c.status==='active'?'<small>Due '+clock(c.deadline)+'</small>':''}</td></tr>`))}`}
if(tab==='research'){v.innerHTML=`<h3>Production and discovery</h3><p class="fine">${esc(a.name)} knows: ${a.known.join(', ')}. Recipes below are an observer view; residents cannot use undiscovered recipes. Experiments spend one timber and one ore to test an authored process. Success depends on crafting skill and seeded chance. This is limited research, not arbitrary chemistry.</p><div class="research-grid">${Object.entries(RECIPES).map(([k,r])=>`<div><strong>${k}</strong><p class="fine">${Object.entries(r.inputs).map(([k,v])=>v+' '+k).join(' + ')}<br>${r.time} minutes · ${r.base?'Known initially':'Hidden initially'}<br>Known by ${world.s.agents.filter(a=>a.known.includes(k)).length}/${world.s.agents.length}</p></div>`).join('')}</div><p class="fine">Tools improve gathering and wear out with use. Coats reduce stress and wear out with time. Batteries release four energy when used; lamps reduce boredom. Teaching can transmit a recipe during conversation.</p><h4>Shared source stocks</h4><div class="inventory">${Object.entries(world.s.resources).map(([k,v])=>`<span>${num(v)} ${k}</span>`).join('')}</div><p class="fine">Sources replenish at explicit scenario rates. Energy is a production input, not currency. Food is consumed and also serves as barter payment.</p>`}
if(tab==='institutions'){v.innerHTML=`<h3>Standing arrangements</h3><p class="fine">No ruler or judge is assigned at creation. Three known, willing workshop users can agree to pool two food each. The available charter grants a reserved workshop slot, equal votes and an exit share. Members contribute 0.15 food after each craft when they can afford it. A coordinator is elected from members and reconsidered every 90 minutes. The charter permits one food of member aid every ten minutes, subject to the coordinator’s reserve policy. This tests one form of cooperative organisation; it does not yet support the full range of governments.</p>${world.s.institutions.map(g=>`<div class="notice-box"><strong>${g.id} · shared workshop</strong><p>Members: ${g.members.map(name).map(esc).join(', ')}. Coordinator: ${esc(name(g.coordinator))}. Treasury: ${num(g.treasury)} food. Member aid distributed: ${Object.values(g.aid||{}).reduce((x,y)=>x+y,0)} food.</p><p>Last ballot: ${Object.entries(g.decisions.at(-1)?.votes||{}).map(([id,v])=>esc(name(id))+': '+v).join(' · ')}</p>${g.members.includes(a.id)?'<button class="button" data-leave="'+g.id+'">'+esc(a.name)+' leaves this association</button>':''}</div>`).join('')||'<p>No standing association has formed in this run.</p>'}<h4>Arbitration selected by the parties</h4>${table(['Mediator','Settlements'],Object.entries(world.s.mediators).sort((a,b)=>b[1]-a[1]).map(([id,n])=>`<tr><td>${esc(name(id))}</td><td>${n}</td></tr>`))}<p class="fine">Both parties must know and sufficiently trust an available mediator. Authority covers held escrow or voluntary restitution. No confiscation power is invented. Three or more selections are counted as a recurring mediator role.</p>`;v.querySelector('[data-leave]')?.addEventListener('click',()=>{pause();world.leave(a);world.validate();save();render(true)})}
if(tab==='labor')renderLaborValues(v);if(tab==='market')renderMarket(v);if(tab==='experiments')renderExperiments();}
function renderLaborValues(v){const resources=RESOURCE_LABOR,baseline=referenceLaborValues(RECIPES,resources),basket={food:1,coat:1,tool:.5};v.innerHTML=`<h3>Reference labor, not a forced price</h3><p class="fine">Each good is measured in standard labor-minutes: the usual skilled time for production plus the labor already represented by its inputs. These are starting assumptions for the experiment, not values agents are forced to trade at. A worker's personal slowness does not raise the benchmark.</p><div class="experiment-controls"><label>Productivity change <select id="labor-good">${Object.keys(RECIPES).map(k=>`<option value="${k}">${k}</option>`).join('')}</select></label><label>New method time <select id="labor-factor"><option value="0.75">75% of old time</option><option value="0.5" selected>50% of old time</option><option value="0.25">25% of old time</option></select></label></div><div id="labor-result"></div><p class="fine">The basket below is one food, one coat and half a tool. It is only a stable comparison yardstick. Later, each currency can be measured against this basket using observed trades.</p><details><summary>Starting extraction labor assumptions</summary><p class="fine">${Object.entries(resources).map(([k,n])=>`${esc(k)}: ${n} standard minutes`).join(' · ')}</p></details>`;const update=()=>{const good=$('#labor-good').value,factor=Number($('#labor-factor').value),values=referenceLaborValues(RECIPES,resources,{[good]:factor});$('#labor-result').innerHTML=`${table(['Good','Direct labor','Input labor','Reference before','After method change'],Object.entries(RECIPES).map(([k,r])=>{const input=Object.entries(r.inputs).reduce((sum,[item,n])=>sum+n*baseline[item],0);return`<tr><td>${esc(k)}</td><td>${num(r.time)}</td><td>${num(input)}</td><td>${num(baseline[k])}</td><td>${num(values[k])}${values[k]!==baseline[k]?` <small>(${num((values[k]/baseline[k]-1)*100)}%)</small>`:''}</td></tr>`}).join(''))}<div class="notice-box"><strong>Fixed basket</strong><p>${num(basketLaborCost(baseline,basket))} labor-minutes before → ${num(basketLaborCost(values,basket))} after this change.</p><p class="fine">Only the selected recipe and goods that use it as an input change. Past transactions are not rewritten.</p></div>`};$('#labor-good').onchange=update;$('#labor-factor').onchange=update;update()}
function renderMarket(v){const transactions=world.s.market.transactions.slice().reverse(),m=world.metrics(),ratio=m.meanTradeLaborRatio,values=referenceLaborValues(RECIPES,RESOURCE_LABOR);v.innerHTML=`<h3>What did a trade actually cost?</h3><p class="fine">This records completed item-for-food exchanges. Food is still the barter good in this prototype, not a universal currency. The benchmark is an accounting comparison only: it does not force a price or change what a creature accepts.</p><div class="lab-metrics"><div>Recorded exchanges<strong>${m.tradeLaborSamples}</strong></div><div>Average labor ratio<strong>${ratio===null?'—':num(ratio)+'×'}</strong></div><div>Food’s labor yardstick<strong>${RESOURCE_LABOR.food} min / food</strong></div></div><p class="fine">A ratio above 1 means the food transferred represents more standard labor than the good’s benchmark; below 1 means less. A ratio is not “fairness”—scarcity, bargaining power and preferences still matter. All observed transactions are retained as an audit trail (latest 250 shown).</p>${transactions.length?table(['Time','Buyer → seller','Good','Food paid','Good benchmark','Paid labor / benchmark'],transactions.map(t=>`<tr><td>${clock(t.minute)}</td><td>${esc(name(t.buyer))} → ${esc(name(t.seller))}</td><td>${esc(t.good)}</td><td>${num(t.foodPaid)}</td><td>${num(t.referenceLabor)} min</td><td>${num(t.paidLabor)} / ${num(t.referenceLabor)} min · <strong>${num(t.ratio)}×</strong><small>contract ${esc(t.contract)}</small></td></tr>`)):'<p>No completed trades yet. Run the village until a sale or commission settles; declined offers and unpaid promises are not counted.</p>'}<details><summary>Current reference goods values</summary>${table(['Good','Reference standard labor'],Object.entries(values).filter(([k])=>RECIPES[k]).map(([k,n])=>`<tr><td>${esc(k)}</td><td>${num(n)} minutes</td></tr>`))}<p class="fine">Changing an assumed productivity method on the Labor values tab changes the reference comparison, but does not rewrite history or automatically reprice an existing trade.</p></details>`}
function graphSVG(a){const n=world.s.agents.length,pos={};world.s.agents.forEach((a,i)=>{const angle=i/n*Math.PI*2-Math.PI/2;pos[a.id]=[180+140*Math.cos(angle),180+140*Math.sin(angle)]});return`<svg viewBox="0 0 360 360" role="img" aria-label="Directional relationships of ${esc(a.name)}"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#668469"/></marker></defs>${Object.values(world.s.edges).filter(r=>r.from===a.id).map(r=>{const [x,y]=pos[r.from],[xx,yy]=pos[r.to],dx=xx-x,dy=yy-y,d=Math.hypot(dx,dy);return`<line x1="${x}" y1="${y}" x2="${xx-dx/d*15}" y2="${yy-dy/d*15}" stroke="${world.trust(a,world.agent(r.to))<.45?'#c57954':'#86a674'}" stroke-width="${1+world.affection(a,world.agent(r.to))/35}" opacity=".65" marker-end="url(#arrow)"/>`}).join('')}${world.s.agents.map(b=>{const[x,y]=pos[b.id];return`<g class="graph-node" data-node="${b.id}" tabindex="0" role="button" aria-label="Inspect ${esc(b.name)}"><circle cx="${x}" cy="${y}" r="13" fill="${b.id===a.id?'#f2cd69':'#d7e5ba'}" stroke="#31516c"/><text x="${x}" y="${y+27}" text-anchor="middle">${esc(b.name)}</text></g>`}).join('')}</svg>`}
function renderEvents(){const filter=$('#event-filter').value,events=world.s.events.filter(e=>filter==='all'||filter==='selected'&&e.actors.includes(selected)||filter==='dispute'&&['breach','theft','settlement','unresolved'].includes(e.type)||filter==='association'&&['association','vote','exit','allocation'].includes(e.type)||e.type===filter);$('#events').innerHTML=events.slice(-55).reverse().map(e=>`<li><time>${clock(e.time)}</time> ${esc(e.text)} <small>${e.id}</small></li>`).join('')||'<li>No matching events yet.</li>'}
function aggregate(result){const groups={};for(const r of result.runs)(groups[r.case]||=[]).push(r);return Object.entries(groups).map(([name,rows])=>({name,n:rows.length,...Object.fromEntries(['trades','meanHunger','gossip','breached','thefts','mediations','repeatMediators','associations','discoveries','foodGini'].map(k=>[k,num(rows.reduce((v,r)=>v+r[k],0)/rows.length)]))}))}
function renderExperiments(){const v=$('#view');v.innerHTML=`<h3>Repeatable experiments</h3><p class="fine">Run 20 independent simulations: four identical seeds across five conditions. Each runs 12 simulated hours with the selected population. The work runs in a background worker so the page stays responsive. Matched seeds preserve initial residents; later random paths can diverge.</p><div class="experiment-controls"><label>Population <select id="batch-count"><option>6</option><option selected>12</option><option>30</option></select></label><button class="button primary" id="batch-run" ${worker?'disabled':''}>Run 20 comparisons</button><button class="button" id="batch-cancel" ${worker?'':'disabled'}>Cancel</button><span id="batch-progress" role="status">${worker?'Running…':batch?'Completed':'Ready'}</span></div><div id="batch-results">${batch?resultsHTML(batch):'<p class="fine">Compare normal conditions, shortage, gossip disabled, institutions disabled and neutral OCEAN values. Outcomes are measurements of these rules—not proof about real societies.</p>'}</div><p class="fine"><a href="experiments.json" download>Download the tested build’s experiment results</a></p><details><summary>What counts as emergence here?</summary><p class="fine">Recurring partners, concentrations of trade, repeated mediator selection and voluntarily formed associations are measured. Mechanisms, recipe sets and cooperative charters are authored. A political ideology or historical sequence is never inferred from a few counters.</p></details>`;$('#batch-run').onclick=startBatch;$('#batch-cancel').onclick=()=>{worker?.terminate();worker=null;$('#batch-progress').textContent='Cancelled; no live world was changed.';$('#batch-run').disabled=false;$('#batch-cancel').disabled=true};$('#batch-download')?.addEventListener('click',()=>download('society-experiments.json',batch))}
function resultsHTML(result){return`<p class="fine">Means across ${result.seeds.length} seeds · ${result.count} residents · ${clock(result.minutes)} per run.</p>${table(['Condition','Trades','Hunger','Gossip','Thefts','Mediations','Repeat mediators','Associations','Discoveries'],aggregate(result).map(r=>`<tr><td>${esc(r.name)}</td>${['trades','meanHunger','gossip','thefts','mediations','repeatMediators','associations','discoveries'].map(k=>`<td>${r[k]}</td>`).join('')}</tr>`))}<button class="button" id="batch-download">Export these results</button>`}
function startBatch(){pause();worker=new Worker('lab-worker.js');const count=Number($('#batch-count').value);$('#batch-run').disabled=true;$('#batch-cancel').disabled=false;worker.onmessage=e=>{const data=e.data;if(data.type==='progress'){if($('#batch-progress'))$('#batch-progress').textContent=`${data.done} / ${data.total} completed`}else{worker.terminate();worker=null;if(data.type==='complete'){batch=data.result;if(tab==='experiments')renderExperiments()}else if($('#batch-progress')){$('#batch-progress').textContent='Experiment failed: '+data.message;$('#batch-run').disabled=false}}};worker.onerror=e=>{worker?.terminate();worker=null;if($('#batch-progress')){$('#batch-progress').textContent='Experiment failed: '+e.message;$('#batch-run').disabled=false}};worker.postMessage({count})}
function frame(now){const dt=Math.min((now-last)/1000,.25);last=now;if(playing&&!document.hidden){elapsed+=dt*Number($('#speed').value);let steps=0;while(elapsed>=1&&steps++<20){world.tick();elapsed--}if(now-lastDraw>500){lastDraw=now;render()}if(now-lastSave>5000){lastSave=now;save()}}requestAnimationFrame(frame)}
window.addEventListener('pagehide',save);setup();render(true);requestAnimationFrame(frame);
})();
